fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    // If the input is empty, just return an empty Vec.
    if n == 0 {
        return Vec::new();
    }

    // Reduce the offset modulo n so we don't do unnecessary work
    // and to handle offsets >= n.
    let k = offset % n;

    // Allocate the result vector with the same length.
    let mut b = Vec::with_capacity(n);

    // For each target index i, pick the element at (i + k) % n from the original.
    for i in 0..n {
        b.push(a[(i + k) % n]);
    }

    b
}

